import React, { useEffect, useRef } from 'react';
import './NiftyChart.css';

const NiftyChart = () => {
  const containerRef = useRef();

  useEffect(() => {
    const current = containerRef.current;
    if (!current) return;

    // Clear previous content
    current.innerHTML = '';

    // Create the widget structure step by step
    const widgetContainer = document.createElement('div');
    widgetContainer.className = 'tradingview-widget-container';

    const widgetInner = document.createElement('div');
    widgetInner.className = 'tradingview-widget-container__widget';
    widgetContainer.appendChild(widgetInner);

    // Create config script with properly formatted JSON
    const configScript = document.createElement('script');
    configScript.type = 'application/json';

    const config = {
      symbol: 'NSE:NIFTY',
      width: '100%',
      height: '350',
      locale: 'en',
      dateRange: '1M',
      colorTheme: 'light',
      trendLineColor: '#14C4B5',
      underLineColor: 'rgba(20, 196, 181, 0.3)',
      underLineBottomColor: 'rgba(20, 196, 181, 0)',
      isTransparent: false,
      autosize: false
    };

    configScript.textContent = JSON.stringify(config);
    widgetContainer.appendChild(configScript);

    // Append to DOM first, THEN load the script
    current.appendChild(widgetContainer);

    // Load TradingView script after DOM is ready
    const script = document.createElement('script');
    script.type = 'text/javascript';
    script.src = 'https://s3.tradingview.com/external-embedding/embed-widget-mini-symbol-overview.js';
    script.async = true;
    current.appendChild(script);

    return () => {
      if (current) {
        current.innerHTML = '';
      }
    };
  }, []);

  return (
    <div className="chart-widget-block">
      <h3 className="chart-title">India Market: NIFTY 50</h3>
      <div ref={containerRef} className="chart-embed"></div>
    </div>
  );
};

export default NiftyChart;
